test "t10 sumas acumuladas" {
    const a = [_]i64{ 1, 2, 3 };
    const out = try prefixSums(std.testing.allocator, &a);
    defer std.testing.allocator.free(out);
    try std.testing.expectEqualSlices(i64, &[_]i64{ 1, 3, 6 }, out);
    const empty = [_]i64{};
    const out2 = try prefixSums(std.testing.allocator, &empty);
    defer std.testing.allocator.free(out2);
    try std.testing.expectEqual(@as(usize, 0), out2.len);
    const b = [_]i64{ -2, 5 };
    const out3 = try prefixSums(std.testing.allocator, &b);
    defer std.testing.allocator.free(out3);
    try std.testing.expectEqualSlices(i64, &[_]i64{ -2, 3 }, out3);
}
